        examples[kind].append((name,fc,dc,files))
for kind in counts:
    print(f'\n[{kind}]')
    for name,fc,dc,files in examples[kind]:
        print(f'{name}\tfiles={fc}\tdirs={dc}\t{','.join(files)}')
