The registry below is intentionally explicit so existing chambers can shape the
standard instead of being flattened into one generic rule.
"""

from __future__ import annotations

from pathlib import Path
import sys


ROOT = Path(__file__).resolve().parents[2]

# Reserved chambers: stable identity shells with a fixed vacancy sentinel.
STUB_PERSONAS: dict[str, str] = {
    ".hecate": "HECATE.md",
    ".bartimaeus": "BARTIMAEUS.md",
    ".zagreus": "ZAGREUS.md",
    ".persephone": "PERSEPHONE.md",
    ".abhorsen": "README.md",
}

# Imported software chambers: runtime/config-backed persona shims.
IMPORTED_PERSONAS: dict[str, str] = {
    ".claude": "CLAUDE.md",
    ".codex": "CODEX.md",
    ".gemini": "GEMINI.md",
    ".serena": "SERENA.md",
}

STUB_SENTINEL = "¿!?"
LOAD_HINTS = (
    "Load mechanism:",
    "Runtime Containment",
    "Governance",
    "Activation status:",
    "Role",
)


def read_text(path: Path) -> str | None:
    try:
        return path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return None


def validate_stub(folder: str, anchor: str, missing: list[str]) -> None:
    folder_path = ROOT / folder
    anchor_path = ROOT / folder / anchor
    stub_path = ROOT / folder / "stub.txt"

    if not folder_path.is_dir():
        missing.append(f"{folder} (folder missing)")
        return

    if not anchor_path.is_file():
        missing.append(f"{folder}/{anchor}")

    if not stub_path.is_file():
        missing.append(f"{folder}/stub.txt")
        return

    content = read_text(stub_path)
    if content is None or content.strip() != STUB_SENTINEL:
        missing.append(f"{folder}/stub.txt (must contain exactly {STUB_SENTINEL!r})")


def validate_imported(folder: str, anchor: str, missing: list[str]) -> None:
    folder_path = ROOT / folder
    anchor_path = ROOT / folder / anchor

    if not folder_path.is_dir():
        missing.append(f"{folder} (folder missing)")
        return

    if not anchor_path.is_file():
        missing.append(f"{folder}/{anchor}")
        return

    content = read_text(anchor_path)
    if content is None:
        missing.append(f"{folder}/{anchor} (not utf-8 readable)")
        return

    if not any(hint in content for hint in LOAD_HINTS):
        missing.append(
            f"{folder}/{anchor} (missing explicit load/governance/runtime marker)"
        )


def main() -> int:
    missing: list[str] = []

    for folder, anchor in STUB_PERSONAS.items():
        validate_stub(folder, anchor, missing)

    for folder, anchor in IMPORTED_PERSONAS.items():
        validate_imported(folder, anchor, missing)

    if missing:
        print("Persona stub standard violations:")
        for item in missing:
            print(f" - {item}")
        return 1

    print("Stub personafolders satisfy the current standard.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Validate the FANDOM canon rulesystem registry.

The registry is the machine-readable bridge between literary worldbuilding and
vault enforcement. This check ensures the canon list is present, named, and
backed by real source files in the vault.
"""

from __future__ import annotations

from pathlib import Path
import re
import sys

import yaml


ROOT = Path(__file__).resolve().parents[2]
REGISTRY = ROOT / "FANDOM-CANON-RULESYSTEMS-2026-05-03.md"


def load_frontmatter(path: Path) -> dict:
    text = path.read_text(encoding="utf-8")
    match = re.match(r"^---\n(.*?)\n---\n", text, re.S)
    if not match:
        raise ValueError(f"{path.name} is missing YAML frontmatter")
    data = yaml.safe_load(match.group(1))
    if not isinstance(data, dict):
        raise ValueError(f"{path.name} frontmatter did not parse as a mapping")
    return data


def main() -> int:
    missing: list[str] = []

    if not REGISTRY.is_file():
        print(f"Missing registry note: {REGISTRY.name}")
        return 1

    try:
        data = load_frontmatter(REGISTRY)
    except Exception as exc:  # pragma: no cover - surfaced in CI
        print(f"Registry parse failed: {exc}")
        return 1

    canons = data.get("canons")
    if not isinstance(canons, list) or not canons:
        print("Registry has no canon entries.")
        return 1

    for canon in canons:
        if not isinstance(canon, dict):
            missing.append("canon entry is not a mapping")
            continue

        display_name = canon.get("display_name") or canon.get("key") or "<unnamed>"
        rulesystem = canon.get("rulesystem")
        primitives = canon.get("primitives")
        source_files = canon.get("source_files")

        if not rulesystem:
            missing.append(f"{display_name}: missing rulesystem")

        if not isinstance(primitives, list) or not primitives:
            missing.append(f"{display_name}: missing primitives")

        if not isinstance(source_files, list) or not source_files:
            missing.append(f"{display_name}: missing source_files")
            continue

        for rel_path in source_files:
            if not isinstance(rel_path, str) or not rel_path.strip():
                missing.append(f"{display_name}: invalid source file entry")
                continue
            if not (ROOT / rel_path).is_file():
                missing.append(f"{display_name}: missing {rel_path}")

    if missing:
        print("FANDOM canon registry violations:")
        for item in missing:
            print(f" - {item}")
        return 1

    print(f"FANDOM canon registry OK: {len(canons)} canon sets checked.")
    for canon in canons:
        if isinstance(canon, dict):
            name = canon.get("display_name") or canon.get("key") or "<unnamed>"
            print(f" - {name}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
